#include "display_fixture.hpp"
#include <limits>
#include <cmath>
static PublishedResult source(AppKind app,const char*kind,vxnn::Shape shape,const std::vector<uint8_t>&raw){auto p=producer();p.lease.app=app;p.lease.artifacts[0].layout=kind;p.lease.artifacts[0].shape=shape;p.lease.artifacts[0].bytes=raw.size();p.lease.artifacts[0].sha=sum(raw);return p;}
static std::vector<uint8_t>oracle(const std::vector<uint8_t>&raw,uint32_t w,uint32_t h,unsigned channels,bool fp,const DisplayLayout&l){std::vector<uint8_t>out(size_t(l.canvas_width)*l.canvas_height*3,0);for(uint32_t y=0;y<l.viewport_height;y++)for(uint32_t x=0;x<l.viewport_width;x++)for(unsigned c=0;c<3;c++){auto sy=uint32_t(uint64_t(y)*h/l.viewport_height),sx=uint32_t(uint64_t(x)*w/l.viewport_width);uint8_t v;if(fp){float f;std::memcpy(&f,raw.data()+(size_t(c)*w*h+size_t(sy)*w+sx)*4,4);v=f<=0?0:f>=255?255:uint8_t(f);}else v=raw[(size_t(sy)*w+sx)*channels+c];out[(size_t(y+l.viewport_y)*l.canvas_width+x+l.viewport_x)*3+c]=v;}return out;}
int main(){RasterComposeCache cache;unsigned cases=0;
 for(unsigned shape=0;shape<6;shape++){bool fp=shape>=4;unsigned channels=shape==3?3:4;uint32_t w=shape==0?256:shape==1?512:shape<4?1280:shape==4?17:1280,h=shape<2?w:shape<4?720:shape==4?13:960;std::vector<uint8_t>raw(size_t(w)*h*(fp?12:channels));if(fp){for(size_t i=0;i<raw.size()/4;i++){float f=(float(int(i%501)-61))/1.7f;std::memcpy(raw.data()+i*4,&f,4);}}else for(size_t i=0;i<raw.size();i++)raw[i]=i%channels==3?255:uint8_t((i*7+i/137)%256);
  auto p=source(fp?AppKind::NN:shape<2?AppKind::P8:AppKind::IMAGE,fp?"CHW_F32":channels==3?"RGB888":"RGBA8888",fp?vxnn::Shape{3,h,w}:vxnn::Shape{h,w,channels},raw);
  for(auto canvas_size:{vxnn::Shape{1280,720},vxnn::Shape{1920,1080}}){auto l=get(raster_page_layout(p.lease,0,canvas_size[0],canvas_size[1]),"original exact layout");auto expected=oracle(raw,w,h,channels,fp,l);auto a=get(cache.compose(p,0,{raw.data(),raw.size()},l),"cache actual compose");need(a->rgb==expected&&a->pixel_sha==sum(expected),"all picture bytes and SHA equal scalar oracle");auto held=a->rgb;auto c=get(cache.compose(p,0,{raw.data(),raw.size()},l),"second held canvas");auto d=get(cache.compose(p,0,{raw.data(),raw.size()},l),"third held canvas");need(a.get()!=c.get()&&a.get()!=d.get()&&c.get()!=d.get()&&a->rgb==held,"held const canvas cannot be aliased or overwritten");auto old=cache.stats();a.reset();c.reset();d.reset();auto reused=get(cache.compose(p,0,{raw.data(),raw.size()},l),"retired canvas reuse");need(reused->rgb==expected&&cache.stats().buffer_reuses>old.buffer_reuses&&cache.stats().retained_canvases<=1,"bounded retired pool reuses capacity");auto bad=raw;bad[0]^=1;need(!cache.compose(p,0,{bad.data(),bad.size()},l),"raw source SHA gate retained");if(!fp&&channels==4){bad=raw;bad[3]=7;auto changed=p;changed.lease.artifacts[0].sha=sum(bad);need(!cache.compose(changed,0,{bad.data(),bad.size()},l),"alpha255 gate retained before reuse");}cases++;}
 }
 auto stats=cache.stats();need(stats.mapping_builds&&stats.mapping_hits&&stats.identity_frames&&stats.scaled_frames,"mapping cache and both paths really executed");std::printf("RASTER_CACHE_SCALAR_BYTE_SHA_HELD_CANVAS_BOUNDED1_POOL_PASS cases=%u maps=%llu hits=%llu reuse=%llu HOST_NOT_DP\n",cases,(unsigned long long)stats.mapping_builds,(unsigned long long)stats.mapping_hits,(unsigned long long)stats.buffer_reuses);
}
